code.cpp:
class Solution {
public:
    int longestBeautifulSubstring(string word) {
        int n = word.size();
        int ans = 0;
        int start = 0;
        int distinct = 1;
        for (int i = 1; i < n; i++) {
            if (word[i] >= word[i - 1]) {
                if (word[i] > word[i - 1]) distinct++;
                if (distinct == 5) ans = max(ans, i - start + 1);
            } else {
                start = i;
                distinct = 1;
            }
        }
        return ans;
    }
};
